visual.code:
SELECT customer, amount,
  SUM(amount) OVER (PARTITION BY customer) AS customer_total
FROM orders;

bricks.template:
SELECT order_id, customer, amount,
  100.0 * amount / SUM(amount) OVER (PARTITION BY [[c]]) AS pct_of_customer
FROM orders;

SELECT customer, order_date, amount,
  SUM(amount) OVER (PARTITION BY customer [[o]] order_date) AS running_total
FROM orders;
